//! Real frames of the DTS-UHD Profile 2 lab sample (frames 0, 1, 1000, 2000, 3000), hex encoded.
//! Frames 0 and 3000 are sync frames. Used only for parser tests.

pub const FRAME_INDICES: [usize; 5] = [0, 1, 1000, 2000, 3000];

pub static FRAMES_HEX: [&str; 5] = [
    "",
    "",
    "",
    "",
    "",
];

pub fn frames() -> Vec<Vec<u8>> {
    FRAMES_HEX
        .iter()
        .map(|h| {
            (0..h.len() / 2)
                .map(|i| u8::from_str_radix(&h[2 * i..2 * i + 2], 16).unwrap())
                .collect()
        })
        .collect()
}
